import org.jetbrains.annotations.Unmodifiable;

public class TileEntityFusionReactorLogicAdapter extends TileEntityFusionReactorBlock implements IReactorLogic<FusionReactorLogic>, IHasMode {

    private static final boolean DEFAULT_ACTIVE_COOLED = false;

    public FusionReactorLogic logicType = FusionReactorLogic.DISABLED;
    private boolean activeCooled = DEFAULT_ACTIVE_COOLED;
    private boolean prevOutputting;

    public TileEntityFusionReactorLogicAdapter(BlockPos pos, BlockState state) {
        super(GeneratorsBlocks.FUSION_REACTOR_LOGIC_ADAPTER, pos, state);
    }

    @Override
    protected boolean onUpdateServer(ServerLevel level, FusionReactorMultiblockData multiblock) {
        boolean needsPacket = super.onUpdateServer(level, multiblock);
        boolean outputting = checkMode();
        if (outputting != prevOutputting) {
            BlockState state = getBlockState();
            Direction side = multiblock.getOutsideSide(worldPosition);
            if (side == null) {
                //Not formed, just update all sides
                level.updateNeighbourForOutputSignal(getBlockPos(), state.getBlock());
            } else if (!EventHooks.onNeighborNotify(level, worldPosition, state, EnumSet.of(side), false).isCanceled()) {
                BlockPos toUpdate = worldPosition.relative(side);
                level.getBlockState(toUpdate).onNeighborChange(level, toUpdate, worldPosition);
                //TODO - 26.3: check weak power updates, updateNeighbourForOutputSignal does some cascading extra stuff
            }
            prevOutputting = outputting;
        }
        return needsPacket;
    }

    public int getRedstoneLevel(Direction side) {
        return level != null && !level.isClientSide() && getMultiblock().isPositionOutsideBounds(worldPosition.relative(side)) && checkMode() ? Redstone.SIGNAL_MAX : Redstone.SIGNAL_NONE;
    }

    public boolean checkMode() {
        if (level != null && level.isClientSide()) {
            return prevOutputting;
        }
        FusionReactorMultiblockData multiblock = getMultiblock();
        if (multiblock.isFormed()) {
            return switch (logicType) {
                case READY -> multiblock.getLastPlasmaTemp() >= multiblock.getIgnitionTemperature(activeCooled);
                case CAPACITY -> multiblock.getLastPlasmaTemp() >= multiblock.getMaxPlasmaTemperature(activeCooled);
                case DEPLETED -> {
                    if (multiblock.fuelTank.isEmpty()) {
                        int injectionPortion = multiblock.getInjectionRate() / 2;
                        //No fuel and no injection rate set, or no fuel and not enough of at least one component
                        yield injectionPortion == 0 || multiblock.deuteriumTank.amountAsLong() < injectionPortion || multiblock.tritiumTank.amountAsLong() < injectionPortion;
                    }
                    yield false;
                }
                case DISABLED -> false;
            };
        }
        return false;
    }

    @Override
    public void readSustainedData(ValueInput input) {
        super.readSustainedData(input);
        this.logicType = input.read(SerializationConstants.LOGIC_TYPE, FusionReactorLogic.CODEC).orElse(FusionReactorLogic.DISABLED);
        activeCooled = input.getBooleanOr(SerializationConstants.ACTIVE_COOLED, DEFAULT_ACTIVE_COOLED);
    }

    @Override
    public void writeSustainedData(ValueOutput output) {
        super.writeSustainedData(output);
        output.store(SerializationConstants.LOGIC_TYPE, FusionReactorLogic.CODEC, logicType);
        output.putBoolean(SerializationConstants.ACTIVE_COOLED, activeCooled);
    }

    @Override
    protected void collectImplicitComponents(DataComponentMap.Builder builder) {
        super.collectImplicitComponents(builder);
        builder.set(GeneratorsDataComponents.FUSION_LOGIC_TYPE, logicType);
        builder.set(GeneratorsDataComponents.ACTIVE_COOLED, activeCooled);
    }

    @Override
    protected void applyImplicitComponents(DataComponentGetter input) {
        super.applyImplicitComponents(input);
        logicType = input.getOrDefault(GeneratorsDataComponents.FUSION_LOGIC_TYPE, FusionReactorLogic.DISABLED);
        activeCooled = input.getOrDefault(GeneratorsDataComponents.ACTIVE_COOLED, DEFAULT_ACTIVE_COOLED);
    }

    @Override
    public void nextMode() {
        activeCooled = !activeCooled;
        markForSave();
    }

    @Override
    public void previousMode() {
        //We only have two modes just flip it
        nextMode();
    }

    @ComputerMethod(nameOverride = "isActiveCooledLogic")
    public boolean isActiveCooled() {
        return activeCooled;
    }

    @Override
    @ComputerMethod(nameOverride = "getLogicMode")
    public FusionReactorLogic getMode() {
        return logicType;
    }

    @Override
    @Unmodifiable
    public List<FusionReactorLogic> getModes() {
        return FusionReactorLogic.VALUES;
    }

    @ComputerMethod(nameOverride = "setLogicMode")
    public void setLogicTypeFromPacket(FusionReactorLogic logicType) {
        if (this.logicType != logicType) {
            this.logicType = logicType;
            markForSave();
        }
    }

    @Override
    public void addContainerTrackers(MekanismContainer container) {
        super.addContainerTrackers(container);
        container.track(SyncableEnum.create(FusionReactorLogic.BY_ID, FusionReactorLogic.DISABLED, this::getMode, value -> logicType = value));
        container.track(SyncableBoolean.create(this::isActiveCooled, value -> activeCooled = value));
        container.track(SyncableBoolean.create(() -> prevOutputting, value -> prevOutputting = value));
    }

    //Methods relating to IComputerTile
    @ComputerMethod
    void setActiveCooledLogic(boolean active) {
        if (activeCooled != active) {
            nextMode();
        }
    }
    //End methods IComputerTile

    public enum FusionReactorLogic implements IReactorLogicMode<FusionReactorLogic>, IHasEnumNameTranslationKey, StringRepresentable {
        DISABLED(GeneratorsLang.REACTOR_LOGIC_DISABLED, GeneratorsLang.DESCRIPTION_REACTOR_DISABLED, Items.GUNPOWDER),
        READY(GeneratorsLang.REACTOR_LOGIC_READY, GeneratorsLang.DESCRIPTION_REACTOR_READY, Items.REDSTONE),
        CAPACITY(GeneratorsLang.REACTOR_LOGIC_CAPACITY, GeneratorsLang.DESCRIPTION_REACTOR_CAPACITY, Items.REDSTONE),
        DEPLETED(GeneratorsLang.REACTOR_LOGIC_DEPLETED, GeneratorsLang.DESCRIPTION_REACTOR_DEPLETED, Items.REDSTONE);

        /// Cached value of [FusionReactorLogic#values()]
        @Unmodifiable
        public static final List<FusionReactorLogic> VALUES = List.of(values());
        public static final Codec<FusionReactorLogic> CODEC = StringRepresentable.fromEnum(FusionReactorLogic::values);
        public static final IntFunction<FusionReactorLogic> BY_ID = ByIdMap.continuous(FusionReactorLogic::ordinal, values(), ByIdMap.OutOfBoundsStrategy.ZERO);
        public static final StreamCodec<ByteBuf, FusionReactorLogic> STREAM_CODEC = ByteBufCodecs.idMapper(BY_ID, FusionReactorLogic::ordinal);

        private final ILangEntry name;
        private final ILangEntry description;
        private final ItemStackTemplate renderStack;
        private final String serializedName;

        FusionReactorLogic(ILangEntry name, ILangEntry description, Item item) {
            this.name = name;
            this.description = description;
            this.renderStack = new ItemStackTemplate(item);
            this.serializedName = name().toLowerCase(Locale.ROOT);
        }

        @Override
        public ItemStack getRenderStack() {
            return renderStack.create();
        }

        @Override
        public String getTranslationKey() {
            return name.getTranslationKey();
        }

        @Override
        public Component getDescription() {
            return description.translate();
        }

        @Override
        public EnumColor getColor() {
            return EnumColor.RED;
        }

        @Override
        public String getSerializedName() {
            return serializedName;
        }
    }
}

package mekanism.common.capabilities.energy;

import java.util.function.Predicate;
import mekanism.api.AutomationType;
import mekanism.api.IContentsListener;
import mekanism.api.SerializationConstants;
import mekanism.api.energy.IEnergyContainer;
import mekanism.api.functions.ConstantPredicates;
import mekanism.common.component.containers.energy.ComponentBackedResistiveEnergyContainer;
import mekanism.common.block.attribute.AttributeEnergy;
import mekanism.common.tile.machine.TileEntityResistiveHeater;
import net.minecraft.world.level.storage.ValueInput;
import net.minecraft.world.level.storage.ValueOutput;
import net.neoforged.neoforge.transfer.transaction.TransactionContext;
import org.jspecify.annotations.Nullable;

public class ResistiveHeaterEnergyContainer extends MachineEnergyContainer<TileEntityResistiveHeater> {

    public static ResistiveHeaterEnergyContainer input(TileEntityResistiveHeater tile, @Nullable IContentsListener listener) {
        AttributeEnergy electricBlock = validateBlock(tile);
        return new ResistiveHeaterEnergyContainer(electricBlock.getStorage(), electricBlock.getUsage(), notExternal, ConstantPredicates.alwaysTrue(), tile, listener);
    }

    private ResistiveHeaterEnergyContainer(long maxEnergy, int energyPerTick, Predicate<AutomationType> canExtract,
          Predicate<AutomationType> canInsert, TileEntityResistiveHeater tile, @Nullable IContentsListener listener) {
        super(maxEnergy, energyPerTick, canExtract, canInsert, tile, listener);
    }

    @Override
    public boolean adjustableRates() {
        return true;
    }

    public void updateEnergyUsage(int energyUsage) {
        //TODO: Do we want to make this support transactions?
        currentEnergyPerTick = energyUsage;
        setMaxEnergy(AttributeEnergy.STORAGE_MULTIPLIER * energyUsage);
    }

    @Override
    public void copyContents(IEnergyContainer other, @Nullable TransactionContext transaction) {
        if (other instanceof ResistiveHeaterEnergyContainer otherContainer) {
            updateEnergyUsage(otherContainer.getEnergyPerTick());
        } else if (other instanceof ComponentBackedResistiveEnergyContainer otherContainer) {
            updateEnergyUsage(otherContainer.getEnergyPerTick());
        }
        super.copyContents(other, transaction);
    }

    @Override
    public void serialize(ValueOutput output) {
        super.serialize(output);
        output.putInt(SerializationConstants.ENERGY_USAGE, getEnergyPerTick());
    }

    @Override
    public void deserialize(ValueInput input) {
        input.getInt(SerializationConstants.ENERGY_USAGE).ifPresent(this::updateEnergyUsage);
        super.deserialize(input);
    }
}

package mekanism.common.component.containers.item;

import java.util.Objects;
import mekanism.api.AutomationType;
import mekanism.api.SerializationConstants;
import mekanism.api.functions.ConstantPredicates;
import mekanism.api.resource.IResourceContainer;
import mekanism.api.resource.ResourceContainerWrapper;
import mekanism.common.component.LockData;
import mekanism.common.component.containers.resource.AttachedResources;
import mekanism.common.inventory.slot.BinInventorySlot;
import mekanism.common.registries.MekanismDataComponents;
import mekanism.common.tier.BinTier;
import mekanism.common.util.ItemAccessUtils;
import net.minecraft.world.level.storage.ValueInput;
import net.minecraft.world.level.storage.ValueOutput;
import net.neoforged.neoforge.transfer.access.ItemAccess;
import net.neoforged.neoforge.transfer.item.ItemResource;
import net.neoforged.neoforge.transfer.transaction.Transaction;
import net.neoforged.neoforge.transfer.transaction.TransactionContext;
import org.jetbrains.annotations.Range;
import org.jspecify.annotations.Nullable;

public class ComponentBackedBinInventorySlot extends ComponentBackedInventorySlot {

    private final boolean isCreative;

    public static ComponentBackedBinInventorySlot create(ItemAccess attachedAccess, int tankIndex) {
        BinTier tier = attachedAccess.getResource().get(MekanismDataComponents.BIN_TIER);
        Objects.requireNonNull(tier, "Attached to should always have a bin tier defined");
        return new ComponentBackedBinInventorySlot(attachedAccess, tankIndex, tier);
    }

    private ComponentBackedBinInventorySlot(ItemAccess attachedAccess, int slotIndex, BinTier tier) {
        super(attachedAccess, slotIndex, ConstantPredicates.alwaysTrueBi(), ConstantPredicates.alwaysTrueBi(), BinInventorySlot.validator, false, tier::getCapacity);
        isCreative = tier.isCreative();
    }

    @Override
    @Range(from = 0, to = Integer.MAX_VALUE)
    protected int insert(AttachedResources<ItemResource> attached, ItemResource currentType, @Range(from = 0, to = Long.MAX_VALUE) long currentAmount, long capacity,
          ItemResource resource, @Range(from = 0, to = Integer.MAX_VALUE) int amount, TransactionContext transaction, AutomationType automationType) {
        if (currentType.isEmpty()) {
            ItemResource lockType = getLockType();
            if (!lockType.isEmpty() && !resource.equals(lockType)) {
                // When locked, we need to make sure the correct item type is being inserted
                return 0;
            } else if (isCreative && automationType.isManual()) {
                //If a player manually inserts into a creative bin, that is empty we need to allow setting the type,
                // Note: We check that it is not external insertion because an empty creative bin acts as a "void" for automation
                try (Transaction simulation = Transaction.open(transaction)) {
                    if (super.insert(attached, currentType, currentAmount, capacity, resource, amount, simulation, automationType) == 0) {
                        return 0;
                    }
                }
                //If we managed to insert anything, set the contents to the maximum amount of that item type
                if (setContents(attached, resource, capacity, transaction)) {
                    //Return that we accepted the entire amount we were passed
                    return amount;
                }
                //If we couldn't update the backing item access, return that we didn't actually insert anything
                return 0;
            }
        }
        if (isCreative) {
            //Return the result without actually changing the contents (accepting without providing any changes
            try (Transaction simulation = Transaction.open(transaction)) {
                return super.insert(attached, currentType, currentAmount, capacity, resource, amount, simulation, automationType);
            }
        }
        return super.insert(attached, currentType, currentAmount, capacity, resource, amount, transaction, automationType);
    }

    @Override
    @Range(from = 0, to = Integer.MAX_VALUE)
    protected int extract(AttachedResources<ItemResource> attached, ItemResource currentType, @Range(from = 0, to = Long.MAX_VALUE) long currentAmount, ItemResource resource,
          @Range(from = 0, to = Integer.MAX_VALUE) int amount, TransactionContext transaction, AutomationType automationType) {
        if (isCreative) {
            try (Transaction simulation = Transaction.open(transaction)) {
                //Use a sub transaction that is not committed to effectively just simulate what will happen without making any changes
                return super.extract(attached, currentType, currentAmount, resource, amount, simulation, automationType);
            }
        }
        return super.extract(attached, currentType, currentAmount, resource, amount, transaction, automationType);
    }

    private boolean setLockType(ItemResource lockType, @Nullable TransactionContext transaction) {
        //Note: The attached access should handle snapshotting the backing stack
        //If anything changed in the item access, that means it was able to perform the transfer, so return that things changed from the call to setContents
        ItemResource resource = attachedAccess.getResource();
        if (resource.isEmpty()) {
            //If the backing item has become empty, just exit and return that we couldn't set the contents
            return false;
        }
        if (lockType.isEmpty()) {
            return ItemAccessUtils.exchange(attachedAccess, resource.without(MekanismDataComponents.LOCK), transaction);
        }
        return ItemAccessUtils.exchange(attachedAccess, resource.with(MekanismDataComponents.LOCK, LockData.create(lockType)), transaction);
    }

    public ItemResource getLockType() {
        return attachedAccess.getResource().getOrDefault(MekanismDataComponents.LOCK, LockData.EMPTY).lock();
    }

    @Override
    public void copyContents(IResourceContainer<ItemResource> other, @Nullable TransactionContext transaction) {
        if (other instanceof ResourceContainerWrapper<ItemResource, ?> wrapper) {
            other = wrapper.getInternal();
        }
        super.copyContents(other, transaction);
        if (other instanceof ComponentBackedBinInventorySlot otherSlot) {
            setLockType(otherSlot.getLockType(), transaction);
        } else if (other instanceof BinInventorySlot otherSlot) {
            setLockType(otherSlot.getLockType(), transaction);
        }
    }

    @Override
    public void serialize(ValueOutput output) {
        super.serialize(output);
        ItemResource lockType = getLockType();
        if (!lockType.isEmpty()) {
            output.store(SerializationConstants.LOCK_TYPE, ItemResource.CODEC, lockType);
        }
    }

    @Override
    public void deserialize(ValueInput input) {
        setLockType(input.read(SerializationConstants.LOCK_TYPE, ItemResource.CODEC).orElse(ItemResource.EMPTY), null);
        super.deserialize(input);
    }
}

package mekanism.common.content.network.transmitter;

import mekanism.api.SerializationConstants;
import mekanism.api.text.EnumColor;
import mekanism.common.MekanismLang;
import mekanism.common.block.attribute.Attribute;
import mekanism.common.content.network.InventoryNetwork;
import mekanism.common.content.transporter.PathfinderCache;
import mekanism.common.tier.TransporterTier;
import mekanism.common.tile.transmitter.TileEntityTransmitter;
import mekanism.common.upgrade.transmitter.LogisticalTransporterUpgradeData;
import mekanism.common.upgrade.transmitter.TransmitterUpgradeData;
import mekanism.common.util.TransporterUtils;
import net.minecraft.core.Direction;
import net.minecraft.core.Holder;
import net.minecraft.network.chat.Component;
import net.minecraft.world.InteractionResult;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.Block;
import net.minecraft.world.level.storage.ValueInput;
import net.minecraft.world.level.storage.ValueOutput;
import net.neoforged.neoforge.transfer.transaction.TransactionContext;
import org.jspecify.annotations.Nullable;

public class LogisticalTransporter extends LogisticalTransporterBase implements IUpgradeableTransmitter<LogisticalTransporterUpgradeData> {

    @Nullable
    private EnumColor color;

    public LogisticalTransporter(Holder<Block> blockProvider, TileEntityTransmitter tile) {
        super(tile, Attribute.getTierNN(blockProvider, TransporterTier.class));
    }

    @Override
    public TransporterTier getTier() {
        return tier;
    }

    @Nullable
    @Override
    public EnumColor getColor() {
        return color;
    }

    public void setColor(@Nullable EnumColor c) {
        color = c;
    }

    @Override
    public InteractionResult onConfigure(Player player, Direction side) {
        setColor(TransporterUtils.increment(getColor()));
        InventoryNetwork network = getTransmitterNetwork();
        if (network != null) {//Should not be null, but double check
            PathfinderCache.onChanged(network);
        }
        TileEntityTransmitter tile = getTransmitterTile();
        tile.markForSave();
        notifyTileChange();
        tile.sendUpdatePacket();
        player.sendOverlayMessage(MekanismLang.TOGGLE_COLOR.translateColored(EnumColor.GRAY, getColorName()));
        return InteractionResult.SUCCESS;
    }

    @Override
    public InteractionResult onRightClick(Level level, Player player, Direction side) {
        player.sendOverlayMessage(MekanismLang.CURRENT_COLOR.translateColored(EnumColor.GRAY, getColorName()));
        return super.onRightClick(level, player, side);
    }

    private Component getColorName() {
        EnumColor color = getColor();
        return color == null ? MekanismLang.NONE.translateColored(EnumColor.WHITE) : color.getColoredName();
    }

    @Override
    public LogisticalTransporterUpgradeData getUpgradeData() {
        return new LogisticalTransporterUpgradeData(redstoneReactive, getConnectionTypesRaw(), getColor(), transit, needsSync, nextId, delay, delayCount);
    }

    @Override
    public boolean dataTypeMatches(TransmitterUpgradeData data) {
        return data instanceof LogisticalTransporterUpgradeData;
    }

    @Override
    public void parseUpgradeData(LogisticalTransporterUpgradeData data, TransactionContext transaction) {
        redstoneReactive = data.redstoneReactive;
        setConnectionTypesRaw(data.connectionTypes);
        setColor(data.color);
        transit.putAll(data.transit);
        needsSync.putAll(data.needsSync);
        nextId = data.nextId;
        delay = data.delay;
        delayCount = data.delayCount;
    }

    @Override
    public void read(ValueInput input) {
        super.read(input);
        setColor(input.read(SerializationConstants.COLOR, EnumColor.CODEC).orElse(null));
    }

    @Override
    public void write(ValueOutput output) {
        super.write(output);
        output.storeNullable(SerializationConstants.COLOR, EnumColor.CODEC, getColor());
    }

    @Override
    public void writeReducedUpdatedTag(ValueOutput output) {
        super.writeReducedUpdatedTag(output);
        output.storeNullable(SerializationConstants.COLOR, EnumColor.CODEC, getColor());
    }

    @Override
    public boolean handleUpdateTag(ValueInput input) {
        boolean refreshModelData = super.handleUpdateTag(input);
        EnumColor color = input.read(SerializationConstants.COLOR, EnumColor.CODEC).orElse(null);
        if (this.color != color) {
            setColor(color);
            //Color changed, mark the model data as needing to be refreshed
            refreshModelData = true;
        }
        return refreshModelData;
    }
}

package mekanism.common.content.network.transmitter;

import java.util.Collection;
import java.util.UUID;
import mekanism.api.IContentsListener;
import mekanism.api.SerializationConstants;
import mekanism.api.heat.IHeatCapacitor;
import mekanism.api.heat.IHeatHandler;
import mekanism.common.block.attribute.Attribute;
import mekanism.common.capabilities.Capabilities;
import mekanism.common.capabilities.heat.CachedAmbientTemperature;
import mekanism.common.capabilities.heat.ITileHeatHandler;
import mekanism.common.capabilities.heat.VariableHeatCapacitor;
import mekanism.common.component.containers.type.ContainerType;
import mekanism.common.content.network.HeatNetwork;
import mekanism.common.lib.Color;
import mekanism.common.lib.transmitter.TransmissionType;
import mekanism.common.lib.transmitter.acceptor.AcceptorCache;
import mekanism.common.tier.ConductorTier;
import mekanism.common.tile.transmitter.TileEntityTransmitter;
import mekanism.common.upgrade.transmitter.ThermodynamicConductorUpgradeData;
import mekanism.common.upgrade.transmitter.TransmitterUpgradeData;
import net.minecraft.core.Direction;
import net.minecraft.core.Holder;
import net.minecraft.world.level.block.Block;
import net.minecraft.world.level.block.entity.BlockEntity;
import net.minecraft.world.level.storage.ValueInput;
import net.minecraft.world.level.storage.ValueOutput;
import net.neoforged.neoforge.transfer.transaction.TransactionContext;
import org.jspecify.annotations.Nullable;

public class ThermodynamicConductor extends Transmitter<IHeatHandler, HeatNetwork, ThermodynamicConductor> implements ITileHeatHandler, IContentsListener,
      IUpgradeableTransmitter<ThermodynamicConductorUpgradeData> {

    private final CachedAmbientTemperature ambientTemperature = new CachedAmbientTemperature(this::getLevel, this::getBlockPos);
    public final ConductorTier tier;
    //Default to negative one, so we know we need to calculate it when needed
    private double clientTemperature = -1;
    public final VariableHeatCapacitor buffer;

    public ThermodynamicConductor(Holder<Block> blockProvider, TileEntityTransmitter tile) {
        this.tier = Attribute.getTierNN(blockProvider, ConductorTier.class);
        super(tile, TransmissionType.HEAT);
        buffer = VariableHeatCapacitor.create(tier.getHeatCapacity(), tier::getInverseConduction, tier::getInverseConductionInsulation, ambientTemperature, this);
    }

    @Override
    protected AcceptorCache<IHeatHandler> createAcceptorCache() {
        return new AcceptorCache<>(getTransmitterTile(), Capabilities.HEAT);
    }

    @Override
    public ConductorTier getTier() {
        return tier;
    }

    @Override
    public HeatNetwork createEmptyNetworkWithID(UUID networkID) {
        return new HeatNetwork(networkID);
    }

    @Override
    public HeatNetwork createNetworkByMerging(Collection<HeatNetwork> networks) {
        return new HeatNetwork(networks);
    }

    @Override
    public void takeShare(@Nullable TransactionContext transaction) {
    }

    @Override
    protected boolean isValidAcceptor(@Nullable BlockEntity tile, Direction side) {
        //Note: We intentionally do not call super here as other elements in the network are intentionally acceptors
        return getAcceptorCache().getConnectedAcceptor(side) != null;
    }

    @Override
    public ThermodynamicConductorUpgradeData getUpgradeData() {
        return new ThermodynamicConductorUpgradeData(redstoneReactive, getConnectionTypesRaw(), buffer.getHeat());
    }

    @Override
    public boolean dataTypeMatches(TransmitterUpgradeData data) {
        return data instanceof ThermodynamicConductorUpgradeData;
    }

    @Override
    public void parseUpgradeData(ThermodynamicConductorUpgradeData data, TransactionContext transaction) {
        redstoneReactive = data.redstoneReactive;
        setConnectionTypesRaw(data.connectionTypes);
        buffer.setHeat(data.heat, transaction);
    }

    @Override
    public void write(ValueOutput output) {
        super.write(output);
        ContainerType.HEAT.saveTo(output, buffer);
    }

    @Override
    public void read(ValueInput input) {
        super.read(input);
        ContainerType.HEAT.readFrom(input, buffer);
    }

    @Override
    public void writeReducedUpdatedTag(ValueOutput output) {
        super.writeReducedUpdatedTag(output);
        output.putDouble(SerializationConstants.HEAT_STORED, buffer.getHeat());
    }

    @Override
    public boolean handleUpdateTag(ValueInput input) {
        boolean refreshModelData = super.handleUpdateTag(input);
        buffer.setHeat(input.getDoubleOr(SerializationConstants.HEAT_STORED, buffer.getHeat()), null);
        return refreshModelData;
    }

    public Color getBaseColor() {
        return tier.getBaseColor();
    }

    @Override
    public IHeatCapacitor getHeatCapacitor(@Nullable Direction side) {
        return buffer;
    }

    public double getTemperature() {
        return buffer.getTemperature();
    }

    @Override
    public void onContentsChanged() {
        if (!isClientSide()) {
            if (clientTemperature == -1) {
                clientTemperature = ambientTemperature.getAsDouble();
            }
            if (Math.abs(buffer.getTemperature() - clientTemperature) > (buffer.getTemperature() / 20)) {
                clientTemperature = buffer.getTemperature();
                getTransmitterTile().sendUpdatePacket();
            }
        }
        getTransmitterTile().setChanged();
    }

    @Override
    public double getAmbientTemperature(Direction side) {
        return ambientTemperature.getTemperature(side);
    }

    @Nullable
    @Override
    public IHeatHandler getAdjacent(Direction side) {
        if (connectionMapContainsSide(getAllCurrentConnections(), side)) {
            //Note: We use the acceptor cache as the heat network is different and the transmitters count the other transmitters in the
            // network as valid acceptors, which means we don't have to differentiate between acceptors and other transmitters here
            return getAcceptorCache().getConnectedAcceptor(side);
        }
        return null;
    }

    @Override
    public boolean countsAsAdjacent(Direction side) {
        //Heat transmitter to heat transmitter, don't count as "adjacent transfer"
        return !hasTransmitterNetwork() || getTransmitterNetworkNN().getTransmitter(getBlockPos().relative(side)) != null;
    }
}

package mekanism.common.content.transporter;

import com.mojang.serialization.Codec;
import io.netty.buffer.ByteBuf;
import it.unimi.dsi.fastutil.longs.LongArrayList;
import it.unimi.dsi.fastutil.longs.LongList;
import java.util.Locale;
import java.util.Optional;
import java.util.function.IntFunction;
import mekanism.api.SerializationConstants;
import mekanism.api.resource.LargeResourceStack;
import mekanism.api.text.EnumColor;
import mekanism.common.content.network.transmitter.LogisticalTransporterBase;
import mekanism.common.content.transporter.TransporterPathfinder.Destination;
import mekanism.common.content.transporter.TransporterPathfinder.IdlePathData;
import mekanism.common.lib.inventory.IAdvancedTransportEjector;
import mekanism.common.lib.inventory.TransitRequest;
import mekanism.common.lib.inventory.TransitRequest.TransitResponse;
import mekanism.common.util.WorldUtils;
import net.minecraft.core.Direction;
import net.minecraft.network.RegistryFriendlyByteBuf;
import net.minecraft.network.codec.ByteBufCodecs;
import net.minecraft.network.codec.StreamCodec;
import net.minecraft.util.ByIdMap;
import net.minecraft.util.StringRepresentable;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.entity.BlockEntity;
import net.minecraft.world.level.storage.ValueInput;
import net.minecraft.world.level.storage.ValueOutput;
import net.neoforged.neoforge.transfer.item.ItemResource;
import net.neoforged.neoforge.transfer.transaction.TransactionContext;
import org.jetbrains.annotations.Contract;
import org.jspecify.annotations.Nullable;

public class TransporterStack {

    //Make sure to call updateForPos before calling this method
    public static StreamCodec<RegistryFriendlyByteBuf, TransporterStack> STREAM_CODEC = StreamCodec.composite(
          EnumColor.OPTIONAL_STREAM_CODEC, stack -> Optional.ofNullable(stack.color),
          ByteBufCodecs.VAR_INT, stack -> stack.progress,
          ByteBufCodecs.VAR_LONG, stack -> stack.originalLocation,
          Path.STREAM_CODEC, TransporterStack::getPathType,
          ByteBufCodecs.optional(ByteBufCodecs.VAR_LONG), stack -> stack.clientNext == Long.MAX_VALUE ? Optional.empty() : Optional.of(stack.clientNext),
          ByteBufCodecs.optional(ByteBufCodecs.VAR_LONG), stack -> stack.clientPrev == Long.MAX_VALUE ? Optional.empty() : Optional.of(stack.clientPrev),
          LargeResourceStack.ITEM_HELPER.streamCodec(), stack -> stack.itemStack,
          (color, progress, originalLocation, pathType, clientNext, clientPrev, itemStack) -> {
              TransporterStack stack = new TransporterStack();
              stack.color = color.orElse(null);
              stack.progress = progress == 0 ? 5 : progress;
              stack.originalLocation = originalLocation;
              stack.pathType = pathType;
              stack.clientNext = clientNext.orElse(Long.MAX_VALUE);
              stack.clientPrev = clientPrev.orElse(Long.MAX_VALUE);
              stack.itemStack = itemStack;
              return stack;
          }
    );

    private LargeResourceStack<ItemResource> itemStack = LargeResourceStack.ITEM_HELPER.empty();

    public int progress;

    @Nullable
    public EnumColor color = null;

    public boolean initiatedPath = false;

    @Nullable
    public Direction idleDir = null;

    //packed BlockPos-es
    public long originalLocation = Long.MAX_VALUE;
    public long homeLocation = Long.MAX_VALUE;
    private long clientNext = Long.MAX_VALUE;
    private long clientPrev = Long.MAX_VALUE;
    //

    @Nullable
    private Path pathType;
    private LongList pathToTarget = new LongArrayList();

    public TransporterStack() {
    }

    private TransporterStack(ValueInput input) {
        this.color = input.read(SerializationConstants.COLOR, EnumColor.CODEC).orElse(null);
        this.progress = input.getIntOr(SerializationConstants.PROGRESS, 0);
        this.originalLocation = input.getLongOr(SerializationConstants.ORIGINAL_LOCATION, Long.MAX_VALUE);
        this.pathType = input.read(SerializationConstants.PATH_TYPE, Path.CODEC).orElse(null);
        this.itemStack = LargeResourceStack.ITEM_HELPER.readOrEmpty(input, SerializationConstants.ITEM);
    }

    public static TransporterStack read(ValueInput input) {
        TransporterStack stack = new TransporterStack(input);
        stack.idleDir = input.read(SerializationConstants.IDLE_DIR, Direction.CODEC).orElse(null);
        stack.homeLocation = input.getLongOr(SerializationConstants.HOME_LOCATION, Long.MAX_VALUE);
        return stack;
    }

    public static TransporterStack readFromUpdate(ValueInput input) {
        TransporterStack stack = new TransporterStack(input);
        stack.clientNext = input.getLongOr(SerializationConstants.NEXT, Long.MAX_VALUE);
        stack.clientPrev = input.getLongOr(SerializationConstants.PREVIOUS, Long.MAX_VALUE);
        return stack;
    }

    private void writeCommon(ValueOutput output) {
        output.storeNullable(SerializationConstants.COLOR, EnumColor.CODEC, color);
        output.putInt(SerializationConstants.PROGRESS, progress);
        output.putLong(SerializationConstants.ORIGINAL_LOCATION, originalLocation);
        LargeResourceStack.ITEM_HELPER.storeNonEmpty(output, SerializationConstants.ITEM, itemStack);
    }

    public void writeToUpdateTag(LogisticalTransporterBase transporter, ValueOutput output) {
        writeCommon(output);
        output.store(SerializationConstants.PATH_TYPE, Path.CODEC, getPathType());
        long next = getNext(transporter);
        if (next != Long.MAX_VALUE) {
            output.putLong(SerializationConstants.NEXT, next);
        }
        long prev = getPrev(transporter);
        if (prev != Long.MAX_VALUE) {
            output.putLong(SerializationConstants.PREVIOUS, prev);
        }
    }

    public void write(ValueOutput output) {
        writeCommon(output);
        //TODO - 26.3: Figure out path type and if we should set it to none when saving to file instead of not saving it
        // given that for syncing we pretend it is none.
        output.storeNullable(SerializationConstants.PATH_TYPE, Path.CODEC, pathType);
        output.storeNullable(SerializationConstants.IDLE_DIR, Direction.CODEC, idleDir);
        if (homeLocation != Long.MAX_VALUE) {
            output.putLong(SerializationConstants.HOME_LOCATION, homeLocation);
        }
    }

    public boolean isEmpty() {
        return itemStack.isEmpty();
    }

    public ItemStack asItemStack() {
        return getItemType().toStack(size());
    }

    public ItemResource getItemType() {
        return itemStack.resource();
    }

    public int size() {
        return itemStack.amountAsInt();
    }

    public void setStack(ItemResource itemType, int amount) {
        this.itemStack = LargeResourceStack.ITEM_HELPER.createStack(itemType, amount);
    }

    private void setPath(Level world, LongList path, Path type, @Nullable TransactionContext transaction) {
        //Make sure old path isn't null
        if (pathType == null || pathType.hasTarget()) {
            //Only update the actual flowing stacks if we want to modify more than our current stack
            TransporterManager.remove(world, this, transaction);
        }
        pathToTarget = path;
        pathType = type;
        if (pathType.hasTarget()) {
            //Only update the actual flowing stacks if we want to modify more than our current stack
            TransporterManager.add(world, this, transaction);
        }
    }

    public boolean hasPath() {
        return pathToTarget.size() >= 2;
    }

    public LongList getPath() {
        return pathToTarget;
    }

    public Path getPathType() {
        return pathType == null ? Path.NONE : pathType;
    }

    public final TransitResponse recalculatePath(Level level, TransitRequest request, @Nullable BlockEntity ignored, LogisticalTransporterBase transporter, int min, @Nullable TransactionContext transaction) {
        return recalculatePath(level, request, transporter, min, transaction);
    }

    public TransitResponse recalculatePath(Level level, TransitRequest request, LogisticalTransporterBase transporter, int min, @Nullable TransactionContext transaction) {
        Destination newPath = TransporterPathfinder.getNewBasePath(transporter, this, request, min, transaction);
        if (newPath == null) {
            return TransitResponse.EMPTY;
        }
        idleDir = null;
        setPath(level, newPath.getPath(), Path.DEST, transaction);
        initiatedPath = true;
        return newPath.getResponseOrEmpty();
    }

    public TransitResponse recalculateRRPath(Level level, TransitRequest request, IAdvancedTransportEjector outputter, LogisticalTransporterBase transporter, int min, @Nullable TransactionContext transaction) {
        Destination newPath = TransporterPathfinder.getNewRRPath(transporter, this, request, outputter, min, transaction);
        if (newPath == null) {
            return TransitResponse.EMPTY;
        }
        idleDir = null;
        setPath(level, newPath.getPath(), Path.DEST, transaction);
        initiatedPath = true;
        return newPath.getResponseOrEmpty();
    }

    public boolean calculateIdle(Level level, LogisticalTransporterBase transporter, @Nullable TransactionContext transaction) {
        IdlePathData newPath = TransporterPathfinder.getIdlePath(transporter, this, transaction);
        if (newPath == null) {
            return false;
        }
        if (newPath.type().isHome()) {
            idleDir = null;
        }
        setPath(level, newPath.path(), newPath.type(), transaction);
        originalLocation = transporter.getWorldPositionLong();
        initiatedPath = true;
        return true;
    }

    public boolean isFinal(LogisticalTransporterBase transporter) {
        return transporter.getWorldPositionLong() == pathToTarget.get(getPathType().hasTarget() ? 1 : 0);
    }

    //TODO - 1.20.5: Re-evaluate this method
    public TransporterStack updateForPos(long pos) {
        clientNext = getNext(pos);
        clientPrev = getPrev(pos);
        return this;
    }

    public long getNext(LogisticalTransporterBase transporter) {
        return transporter.isClientSide() ? clientNext : getNext(transporter.getWorldPositionLong());
    }

    private long getNext(long pos) {
        int index = pathToTarget.indexOf(pos) - 1;
        if (index < 0) {
            return Long.MAX_VALUE;
        }
        return pathToTarget.getLong(index);
    }

    public long getPrev(LogisticalTransporterBase transporter) {
        return transporter.isClientSide() ? clientPrev : getPrev(transporter.getBlockPos().asLong());
    }

    private long getPrev(long pos) {
        int index = pathToTarget.indexOf(pos) + 1;
        if (index < pathToTarget.size()) {
            return pathToTarget.getLong(index);
        }
        return originalLocation;
    }

    public Direction getSide(LogisticalTransporterBase transporter) {
        Direction side = null;
        if (progress < 50) {
            long prev = getPrev(transporter);
            if (prev != Long.MAX_VALUE) {
                side = WorldUtils.sideDifference(transporter.getBlockPos().asLong(), prev);
            }
        } else {
            long next = getNext(transporter);
            if (next != Long.MAX_VALUE) {
                side = WorldUtils.sideDifference(next, transporter.getBlockPos().asLong());
            }
        }
        //sideDifference can return null
        //TODO: Look into implications further about what side should be returned.
        // This is mainly to stop a crash I randomly encountered but was unable to reproduce.
        // (I believe the difference returns null when it is the "same" transporter somehow or something)
        return side == null ? Direction.DOWN : side;
    }

    public Direction getSide(long pos, long target) {
        Direction side = null;
        if (target != Long.MAX_VALUE) {
            side = WorldUtils.sideDifference(target, pos);
        }
        //TODO: See getSide(Transporter) for why we null check and then return down
        return side == null ? Direction.DOWN : side;
    }

    @Contract("null, _, _ -> false")
    public boolean canInsertToTransporter(@Nullable LogisticalTransporterBase transporter, Direction from, @Nullable LogisticalTransporterBase transporterFrom) {
        if (transporter == null) {
            return false;
        }
        //If the color is valid, make sure that the connection is valid
        EnumColor color = transporter.getColor();
        return (color == null || color == this.color) && transporter.canConnectMutual(from.getOpposite(), transporterFrom);
    }

    @Contract("null, _, _ -> false")
    public boolean canInsertToTransporter(@Nullable LogisticalTransporterBase transporter, Direction from, @Nullable BlockEntity tileFrom) {
        if (transporter == null) {
            return false;
        }
        //If the color is valid, make sure that the connection is valid
        EnumColor color = transporter.getColor();
        return (color == null || color == this.color) && transporter.canConnectMutual(from.getOpposite(), tileFrom);
    }

    public long getDest() {
        return pathToTarget.getFirst();
    }

    @Nullable
    public Direction getSideOfDest() {
        if (hasPath()) {
            long lastTransporter = pathToTarget.getLong(1);
            return WorldUtils.sideDifference(lastTransporter, getDest());
        }
        return null;
    }

    public enum Path implements StringRepresentable {
        DEST,
        HOME,
        NONE;

        public static final Codec<Path> CODEC = StringRepresentable.fromEnum(Path::values);
        public static final IntFunction<Path> BY_ID = ByIdMap.continuous(Path::ordinal, values(), ByIdMap.OutOfBoundsStrategy.WRAP);
        public static final StreamCodec<ByteBuf, Path> STREAM_CODEC = ByteBufCodecs.idMapper(BY_ID, Path::ordinal);

        private final String serializedName;

        Path() {
            this.serializedName = name().toLowerCase(Locale.ROOT);
        }

        public boolean hasTarget() {
            return this != NONE;
        }

        public boolean noTarget() {
            return this == NONE;
        }

        public boolean isHome() {
            return this == HOME;
        }

        @Override
        public String getSerializedName() {
            return serializedName;
        }
    }
}

package mekanism.common.inventory.slot;

import java.util.Objects;
import java.util.function.Predicate;
import mekanism.api.AutomationType;
import mekanism.api.IContentsListener;
import mekanism.api.SerializationConstants;
import mekanism.api.functions.ConstantPredicates;
import mekanism.api.resource.IResourceContainer;
import mekanism.api.resource.ResourceContainerWrapper;
import mekanism.common.component.containers.item.ComponentBackedBinInventorySlot;
import mekanism.common.inventory.container.slot.InventoryContainerSlot;
import mekanism.common.item.block.ItemBlockBin;
import mekanism.common.tier.BinTier;
import net.minecraft.world.level.storage.ValueInput;
import net.minecraft.world.level.storage.ValueOutput;
import net.neoforged.neoforge.transfer.TransferPreconditions;
import net.neoforged.neoforge.transfer.item.ItemResource;
import net.neoforged.neoforge.transfer.transaction.SnapshotJournal;
import net.neoforged.neoforge.transfer.transaction.Transaction;
import net.neoforged.neoforge.transfer.transaction.TransactionContext;
import org.jetbrains.annotations.Range;
import org.jspecify.annotations.Nullable;

public class BinInventorySlot extends BasicInventorySlot {

    public static final Predicate<ItemResource> validator = itemType -> !(itemType.getItem() instanceof ItemBlockBin);

    public static BinInventorySlot create(@Nullable IContentsListener listener, BinTier tier) {
        Objects.requireNonNull(tier, "Bin tier cannot be null");
        return new BinInventorySlot(listener, tier);
    }

    private final LockTypeJournal lockTypeJournal = new LockTypeJournal();
    private final boolean isCreative;

    private BinInventorySlot(@Nullable IContentsListener listener, BinTier tier) {
        super(tier.getCapacity(), ConstantPredicates.alwaysTrueBi(), ConstantPredicates.alwaysTrueBi(), validator, null, null, listener, 0, 0);
        isCreative = tier.isCreative();
        obeyStackLimit = false;
    }

    @Override
    @Range(from = 0, to = Integer.MAX_VALUE)
    public int insert(ItemResource resource, @Range(from = 0, to = Integer.MAX_VALUE) int amount, TransactionContext transaction, AutomationType automationType) {
        TransferPreconditions.checkNonEmptyNonNegative(resource, amount);
        if (amount == 0) {
            //"Fail quick" if there is nothing to add
            return 0;
        }
        if (isEmpty()) {
            if (isLocked() && !lockTypeJournal.lockType.equals(resource)) {
                // When locked, we need to make sure the correct item type is being inserted
                return 0;
            } else if (isCreative && automationType.isManual()) {
                //If a player manually inserts into a creative bin, that is empty we need to allow setting the type,
                // Note: We check that it is not external insertion because an empty creative bin acts as a "void" for automation
                try (Transaction simulation = Transaction.open(transaction)) {
                    if (super.insert(resource, amount, simulation, automationType) == 0) {
                        return 0;
                    }
                }
                //If we managed to insert anything, set the contents to the maximum amount of that item type
                // Note: We just set it as unchecked as we have already validated it
                setContents(resource, capacityAsLong(resource), transaction);
                //Return that we accepted the entire amount we were passed
                return amount;
            }
        }
        if (isCreative) {
            //Return the result without actually changing the contents (accepting without providing any changes)
            try (Transaction simulation = Transaction.open(transaction)) {
                return super.insert(resource, amount, simulation, automationType);
            }
        }
        return super.insert(resource, amount, transaction, automationType);
    }

    @Override
    @Range(from = 0, to = Integer.MAX_VALUE)
    public int extract(ItemResource resource, @Range(from = 0, to = Integer.MAX_VALUE) int amount, TransactionContext transaction, AutomationType automationType) {
        TransferPreconditions.checkNonEmptyNonNegative(resource, amount);
        if (isEmpty() || amount == 0) {
            //"Fail quick" if we are empty, nothing is being extracted
            return 0;
        }
        if (isCreative) {
            try (Transaction simulation = Transaction.open(transaction)) {
                //Use a sub transaction that is not committed to effectively just simulate what will happen without making any changes
                return super.extract(resource, amount, simulation, automationType);
            }
        }
        return super.extract(resource, amount, transaction, automationType);
    }

    @Nullable
    @Override
    public InventoryContainerSlot createContainerSlot() {
        return null;
    }

    /// Modifies the lock state of the slot.
    ///
    /// @param lock if the slot should be locked
    ///
    /// @return if the lock state was modified
    public boolean setLocked(boolean lock) {
        // Don't lock if:
        // - We are a creative bin
        // - We already have the same state as the one we're supposed to switch to
        // - We were asked to lock, but we're empty
        if (isCreative || isLocked() == lock || (lock && isEmpty())) {
            return false;
        }
        setLockType(lock ? resource() : ItemResource.EMPTY, null);
        return true;
    }

    /// For use by tier installers and parsing placement data, do not use this in place of [#setLocked(boolean)]
    public void setLockType(ItemResource lockType, @Nullable TransactionContext transaction) {
        lockTypeJournal.setLockType(lockType, transaction);
    }

    public boolean isLocked() {
        return !lockTypeJournal.lockType.isEmpty();
    }

    public ItemResource getBinItemType() {
        return isLocked() ? lockTypeJournal.lockType : resource();
    }

    public ItemResource getLockType() {
        return lockTypeJournal.lockType;
    }

    @Override
    public void copyContents(IResourceContainer<ItemResource> other, @Nullable TransactionContext transaction) {
        if (other instanceof ResourceContainerWrapper<ItemResource, ?> wrapper) {
            other = wrapper.getInternal();
        }
        super.copyContents(other, transaction);
        if (other instanceof BinInventorySlot otherSlot) {
            setLockType(otherSlot.getLockType(), transaction);
        } else if (other instanceof ComponentBackedBinInventorySlot otherSlot) {
            setLockType(otherSlot.getLockType(), transaction);
        }
    }

    @Override
    public void serialize(ValueOutput output) {
        //Note: While we are able to store this extra data for saving and stuff, when converting to an item we need to have
        // the tile copy the lock stack as a component
        super.serialize(output);
        if (isLocked()) {
            output.store(SerializationConstants.LOCK_TYPE, ItemResource.CODEC, lockTypeJournal.lockType);
        }
    }

    @Override
    public void deserialize(ValueInput input) {
        setLockType(input.read(SerializationConstants.LOCK_TYPE, ItemResource.CODEC).orElse(ItemResource.EMPTY), null);
        super.deserialize(input);
    }

    private static class LockTypeJournal extends SnapshotJournal<ItemResource> {

        private ItemResource lockType = ItemResource.EMPTY;

        public void setLockType(ItemResource lockType, @Nullable TransactionContext transaction) {
            if (transaction != null) {
                updateSnapshots(transaction);
            }
            this.lockType = lockType;
        }

        @Override
        protected ItemResource createSnapshot() {
            return lockType;
        }

        @Override
        protected void revertToSnapshot(ItemResource snapshot) {
            lockType = snapshot;
        }
    }
}

