            }
        }
    }

    public final boolean isRedstoneActivated() {
        return !supportsRedstone() ||
               switch (controlType) {
                   case DISABLED -> true;
                   case HIGH -> isPowered();
                   case LOW -> !isPowered();
                   case PULSE -> isPowered() && !redstoneLastTick;
               };
